package com.openggf.game.soniccd;
import com.openggf.game.soniccd.level.*;
import com.openggf.game.soniccd.objects.*;
import com.openggf.game.soniccd.player.*;
import com.openggf.game.soniccd.resources.*;
import org.junit.jupiter.api.Test;
import java.util.*;
import static org.junit.jupiter.api.Assertions.*;
import static com.openggf.game.soniccd.objects.CdObjectState.ByteField.*;
import static com.openggf.game.soniccd.objects.CdObjectState.WordField.*;
import static com.openggf.game.soniccd.objects.CdObjectState.LongField.*;
/** Tests FIRST, Java UNRUN. Genuine configured C/D cold loading/actual Core/Host/World/Frame stacks.
 * Public-pool Boss ingress is explicitly CONSTRUCTED component programme input, not natural fight,
 * route, actor hydration, FULL admission/current readiness or pixel certification. */
class TestSonicCdAct3FutureBossWorld {
    @Test void actualColdBossInitAppendsFourThenStoresFrameAndCpuPalette()throws Exception {for(var a:TestCdR13PlaneSources.actual())try(var f=new TestSonicCdAct3FutureWorldHost.Fixture(a,3)){f.ready();seed(f,127,0);var before=f.core.state();f.core.service(0);assertEquals(1,Collections.frequency(f.core.state().calls(),SonicCdAct3FutureLoadingVisit.Call.BOSS_PLC_APPEND));assertEquals(1,f.frame.environment().movement().bounds().bossFight());var s=f.host.placement().pool().state(127);assertEquals(2,s.routine());assertEquals(0xC52,s.centreX());assertEquals(0x78,s.centreY());assertEquals(CdR13BossAssets.bind(a).range(CdR13BossAssets.Table.EGGMAN_MAPPINGS).nativeAddress(),s.longBits(MAPPINGS));assertPreparedBossHead(f.core.state().section(),a.plcs().get(4).entries().getFirst().sourceNativeAddress());assertSame(before.normalPalette(),f.core.state().displayedPalette());assertFalse(f.core.failed());}}
    @Test void nextOriginalBossEntryKeepsActualTargetRightIndependentOfCurrentCamera()throws Exception {for(var a:TestCdR13PlaneSources.actual())try(var f=new TestSonicCdAct3FutureWorldHost.Fixture(a,3)){f.ready();seed(f,127,0);f.core.service(0);f.core.service(0);assertEquals(0xAC0,f.frame.environment().movement().bounds().right());assertEquals(0xAC0,f.host.targetRightBoundWord().orElseThrow());assertEquals(0,f.host.scroll().foreground().cameraX());assertFalse(f.core.failed());}}
    @Test void fiveRealBossInitsFillFifteenDescriptorsWithoutInventedCapacityPreflight()throws Exception {for(var a:TestCdR13PlaneSources.actual())try(var f=new TestSonicCdAct3FutureWorldHost.Fixture(a,3)){f.ready();for(int whole=123;whole<128;whole++)seed(f,whole,0);f.core.service(0);assertEquals(5,Collections.frequency(f.core.state().calls(),SonicCdAct3FutureLoadingVisit.Call.BOSS_PLC_APPEND));var section=f.core.state().section();assertPreparedBossHead(section,a.plcs().get(4).entries().getFirst().sourceNativeAddress());var raw=section.queue().bytes();for(int n=0;n<15;n++){var expected=a.plcs().get(4).entries().get(n%3);assertEquals(n==0?section.decoder().orElseThrow().sourcePointer():expected.sourceNativeAddress(),raw.unsignedLong(n*6));assertEquals(expected.vramAddress(),raw.unsignedWord(n*6+4));}assertEquals(0,raw.unsignedLong(90));}}
    @Test void sixthActualBossAppendRetainsOneCompletedRowAndOriginalFaultPrefix()throws Exception {for(var a:TestCdR13PlaneSources.actual())try(var f=new TestSonicCdAct3FutureWorldHost.Fixture(a,3)){f.ready();for(int whole=122;whole<128;whole++)seed(f,whole,0);var pool=f.host.placement().pool();var before=f.core.state().section();var error=assertThrows(CdR13SectionArt.SectionArtException.class,()->f.core.service(0));assertSame(error.state(),f.core.state().section());assertTrue(f.core.failed());assertEquals(5,Collections.frequency(f.core.state().calls(),SonicCdAct3FutureLoadingVisit.Call.BOSS_PLC_APPEND));assertEquals(0,pool.state(127).routine());assertEquals(1,f.frame.environment().movement().bounds().bossFight());var raw=error.state().queue().bytes();for(int n=0;n<16;n++)assertEquals(a.plcs().get(4).entries().get(n%3).sourceNativeAddress(),raw.unsignedLong(n*6));assertEquals(32,CdR13ArtResidency.readTile(error.state().residency(),0xB4A0/32).length());assertSame(before.codeTable(),error.state().codeTable());assertEquals(before.decoder(),error.state().decoder());assertEquals(before.savedDecoder(),error.state().savedDecoder());assertThrows(IllegalStateException.class,()->f.core.service(0));}}
    @Test void originalExitReadsAndClampsBothRealBoundOwnersThenDeletesWithoutDraw()throws Exception {for(var a:TestCdR13PlaneSources.actual())try(var f=new TestSonicCdAct3FutureWorldHost.Fixture(a,3)){f.ready();seed(f,127,10);f.core.service(0);assertArrayEquals(new byte[64],f.host.placement().pool().state(127).copyBytes());assertEquals(a.bounds().right(),f.frame.environment().movement().bounds().right());assertEquals(a.bounds().right(),f.host.targetRightBoundWord().orElseThrow());assertFalse(f.core.failed());}}
    @Test void originalFocusUsesFrameCentreThroughActualPreparedPublication()throws Exception {for(var a:TestCdR13PlaneSources.actual())try(var f=new TestSonicCdAct3FutureWorldHost.Fixture(a,3)){f.ready();seed(f,127,12);int centre=f.frame.environment().movement().globals().cameraYCentre();f.core.service(0);assertEquals(centre+6,f.frame.environment().movement().globals().cameraYCentre());assertEquals(12,f.host.placement().pool().state(127).routine());assertTrue(f.host.sounds().stream().noneMatch(s->s instanceof SonicCdGameModule.PastR13BossSubCpu));}}
    @Test void originalDefeatCallsSharedAddPointsOnceAfterNativeExplosionAllocation()throws Exception {for(var a:TestCdR13PlaneSources.actual())try(var f=new TestSonicCdAct3FutureWorldHost.Fixture(a,3)){f.ready();seed(f,127,6);var pool=f.host.placement().pool();pool.write(pool.state(127).moveByte(BOSS_COUNTER,0x77).moveByte(SPRITE_FLAGS,0x84));int score=f.host.globals().score().score();f.core.service(0);assertEquals(score+100,f.host.globals().score().score());assertEquals(8,pool.state(127).routine());assertTrue(f.host.sounds().stream().anyMatch(x->x instanceof SonicCdGameModule.PastR13BossFm fm&&fm.sound()==CdR13Boss.FmSound.EXPLOSION));assertTrue(pool.capture().slots().stream().anyMatch(s->s.id()==0x18&&s.unsignedByte(ROUTINE_2)==255));assertFalse(f.core.failed());}}
    @Test void genuineMachineCreationUsesFourteenFreshPhysicalAllocations()throws Exception {for(var a:TestCdR13PlaneSources.actual())try(var f=new TestSonicCdAct3FutureWorldHost.Fixture(a,3)){f.ready();seed(f,127,14);var pool=f.host.placement().pool();pool.write(pool.state(127).moveByte(BOSS_COUNTER,0x3B));f.core.service(0);assertEquals(4,pool.state(127).routine());assertEquals(3,pool.state(127).unsignedByte(BOSS_COUNTER));assertEquals(14,pool.capture().slots().stream().filter(s->s.id()>=0x2B&&s.id()<=0x32).count());assertFalse(f.core.failed());}}
    @Test void actualEscapeChoosesOriginalGoodOrBadCommandAndNativeCapsulePalette()throws Exception {for(var a:TestCdR13PlaneSources.actual())try(var f=new TestSonicCdAct3FutureWorldHost.Fixture(a,3)){f.ready();seed(f,127,8);var pool=f.host.placement().pool();pool.write(pool.state(127).moveByte(ROUTINE_2,1).moveWord(X,0xC80));var displayed=f.core.state().normalPalette();f.core.service(0);assertArrayEquals(new byte[64],pool.state(127).copyBytes());assertEquals(0,f.frame.environment().movement().bounds().bossFight());assertEquals(0,f.host.globals().bossFlagsByte().orElseThrow());var sounds=f.host.sounds().stream().filter(SonicCdGameModule.PastR13BossSubCpu.class::isInstance).map(SonicCdGameModule.PastR13BossSubCpu.class::cast).toList();assertEquals(1,sounds.size());assertEquals(a.identity().file()==CdNativeFile.R13C?CdR13Boss.CpuCommand.GOOD_MUSIC:CdR13Boss.CpuCommand.BAD_MUSIC,sounds.getFirst().command());assertSame(displayed,f.core.state().displayedPalette());}}
    @Test void originalBossStepReplaysOnlyFromGenuineFullComponentCapture()throws Exception {for(var a:TestCdR13PlaneSources.actual())try(var f=new TestSonicCdAct3FutureWorldHost.Fixture(a,3)){f.ready();seed(f,127,0);var original=f.core.capture();f.core.service(0);var actor=f.frame.captureActor();var shared=f.frame.captureShared();var host=f.host.capture();var state=f.core.state();f.core.restore(original);f.core.service(0);assertEquals(actor,f.frame.captureActor());assertEquals(shared.environment(),f.frame.environment());assertEquals(shared.vIntClock(),f.frame.vIntClock());assertEquals(host,f.host.capture());assertEquals(state.section(),f.core.state().section());assertEquals(state.calls(),f.core.state().calls());assertArrayEquals(state.normalPalette().copy(),f.core.state().normalPalette().copy());}}
    @Test void idleBossHostPreparationCannotGrantActualWorldInvocation()throws Exception {try(var f=new TestSonicCdAct3FutureWorldHost.Fixture(TestCdR13PlaneSources.actual().getFirst(),3)){f.ready();var actor=f.frame.captureActor();assertThrows(IllegalStateException.class,()->f.world.requireObjectPass(null));assertThrows(IllegalStateException.class,()->f.host.readBossOwners(null));assertEquals(actor,f.frame.captureActor());assertFalse(f.core.failed());}}
    @Test void remainingPowerupStillStopsAtGenuineUnboundPhysicalIdentityAfterEndFamiliesAreBound()throws Exception {try(var f=new TestSonicCdAct3FutureWorldHost.Fixture(TestCdR13PlaneSources.actual().getFirst(),3)){f.ready();var pool=f.host.placement().pool();pool.write(pool.state(127).moveByte(ID,0x03));var stopped=assertThrows(SonicCdAct3FutureObjectPass.Unowned.class,()->f.core.service(0));assertEquals(SonicCdAct3FutureObjectPass.Boundary.OBJECT_FAMILY,stopped.boundary());assertEquals(0x03,stopped.value());assertTrue(f.core.failed());}}
    /** Main's genuine final PREPARE_PLC parses the first descriptor; later rows remain raw.
     * No exact observed cursor delta is fitted here: the original producer's typed cursor
     * and authenticated stream origin/header describe the published state. */
    private static void assertPreparedBossHead(CdR13SectionArt.State section,long source) {
        var decoder=section.decoder().orElseThrow();
        assertEquals(source,decoder.nativeAddress());
        assertEquals(decoder.sourcePointer(),section.queue().headSource());
        assertEquals(decoder.sourceBytes().unsignedWord(0),decoder.headerWord());
        assertEquals(decoder.headerWord()&0x7FFF,section.remainingTilesWord());
        assertEquals(section.remainingTilesWord(),decoder.remainingTiles());
        assertTrue(decoder.inputOffset()>2);
        assertTrue(decoder.inputOffset()<=decoder.sourceBytes().length());
    }
    private static void seed(TestSonicCdAct3FutureWorldHost.Fixture f,int whole,int routine){var data=CdR13BossAssets.bind(f.assets);var pool=f.host.placement().pool();pool.write(pool.state(whole).moveByte(ID,0x2A).moveByte(ROUTINE,routine).moveByte(ANIMATION,routine==0?0:1).moveByte(SPRITE_FLAGS,4).moveByte(PRIORITY,6).moveByte(WIDTH,0x14).moveByte(Y_RADIUS,8).moveWord(X,0xC52).moveWord(Y,0x78).moveWord(TILE,0x3FD).moveLong(MAPPINGS,data.range(CdR13BossAssets.Table.EGGMAN_MAPPINGS).nativeAddress()));}
}
